function throttle(fn, wait, clock) {
  let last = -Infinity;
  let timer = null;
  let pending = null;
  const run = (args) => {
    last = clock.now();
    fn(...args);
  };
  return (...args) => {
    const elapsed = clock.now() - last;
    if (elapsed >= wait && timer === null) {
      run(args);
      return;
